<template>
  <div class="setting">
    <div class="top">
      <label :id="name">{{ label }}</label>
      <Toggle v-model="value" @change="change" :labelledby="name" :describedby="name"/>
    </div>
    <small>{{ description }}</small>
  </div>
</template>

<script>
import Toggle from '@vueform/toggle';

export default {
  name: "ToggleOption",
  props: ['id', 'label', 'name', 'description'],
  components: {
    Toggle
  },
  data() {
    return {
      value: false,
    }
  },
  methods: {
    change() {
      // eslint-disable-next-line no-undef
      mp.trigger('MenuChangeSettings', this.id, this.value);
    }
  },
}
</script>

<style scoped lang="scss">
.setting {
  color: $white-text;
  margin-bottom: 15px;

  .top {
    display: flex;
    justify-content: flex-start;
    align-items: center;

    label {
      margin-right: 10px;
    }
  }

  small {
    color: $gray-text;
  }
}
</style>