<template>
  <div class="setting">
    <div class="top">
      <label>{{ label }}</label>
      <div :id="name" :class="{ listening: listening }" class="key">{{ value }}</div>
    </div>
    <small>{{ description }}</small>
  </div>
</template>

<script>
import $ from 'jquery';

export default {
  name: "BindOption",
  props: ['id', 'label', 'name', 'description',],
  data() {
    return {
      value: 'N/A',
      listening: false
    }
  },
  mounted() {
    let that = this;
    $(`#${that.name}`).on("click", function () {
      that.listening = true;
      $(document).off('keyup');
      // eslint-disable-next-line no-undef
      //mp.trigger('MenuToggleTyping', true);
      $(document).keyup(function (e) {
        let code = e.keyCode | e.which;
        that.value = e.key.toUpperCase();
        // eslint-disable-next-line no-undef
        mp.trigger('MenuChangeSettings', that.id, code);
        $(document).off('keyup');
        that.listening = false;
        // eslint-disable-next-line no-undef
        mp.trigger('MenuToggleTyping', false);
      });

      setTimeout(() => {
        if (!that.listening) return;
        $(document).off('keyup');
        that.listening = false;
        // eslint-disable-next-line no-undef
        mp.trigger('MenuToggleTyping', false);
      }, 5000);
    });
  },
}
</script>

<style scoped lang="scss">
.listening {
  background: $blue !important;
  border-color: $blue !important;
}

.key {
  background: transparent;
  border: 2px solid $gray-text;
  border-radius: 15px;
  min-width: 35px;
  padding: 2px 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: bolder;
  font-size: 17px;
  transition: all 0.4s;

  &:hover {
    background: $blue;
    border-color: $blue;
  }
}

.setting {
  color: $white-text;
  margin-bottom: 15px;

  .top {
    display: flex;
    justify-content: flex-start;
    align-items: center;

    label {
      margin-right: 10px;
    }
  }

  small {
    color: $gray-text;
  }
}
</style>