<template>
  <div style="overflow: visible" v-show="title === selectedTitle">
    <slot />
  </div>
</template>

<script>
import { inject } from "vue";

export default {
  name: "Tab",
  props: ["title"],
  setup() {
    const selectedTitle = inject("selectedTitle");
    const tabTitles = inject("tabTitles");

    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
div {
  min-width: 100%;
}
</style>
